package owl.nh;
import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
final class SlayerPanel extends JFrame {
 private final Timer timer;
 SlayerPanel(CombatRuntime runtime,SlayerController fighter){
  super("Turbo Slayer");TurboBranding.apply(this);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
  JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));
  JLabel selected=new JLabel("Selected: "+fighter.selected),progress=new JLabel("Ready");
  JTextArea status=new JTextArea(5,42);status.setEditable(false);status.setLineWrap(true);status.setWrapStyleWord(true);
  JComboBox<String> mode=choices("Standard NPC","Tormented demons — Orion setup required");mode.setSelectedIndex(fighter.mobMode.ordinal());
  JSpinner amount=new JSpinner(new SpinnerNumberModel(1,1,10000,1)),hp=new JSpinner(new SpinnerNumberModel(fighter.survival.hp,0,255,1)),points=new JSpinner(new SpinnerNumberModel(fighter.survival.prayer,0,255,1));
  amount.setToolTipText("Leave at 1 to use the equipped Slayer helmet's remaining task count; values above 1 are explicit manual goals.");
  hp.setToolTipText("Eat below this HP target; 0 disables. Requires edible food; brews are not used.");points.setToolTipText("Drink a recognized prayer restore below this target; 0 disables.");
  JComboBox<String> offensive=choices("None","Mystic will","Mystic lore","Mystic might","Augury","Sharp eye","Hawk eye","Eagle eye","Rigour","Burst of strength","Superhuman strength","Ultimate strength","Chivalry","Piety");
  JComboBox<String> defensive=choices("None","Protect from magic","Protect from missiles","Protect from melee");select(offensive,fighter.offensivePrayer);select(defensive,fighter.defensivePrayer);
  JCheckBox automatic=new JCheckBox("Auto-scan NPC stats and choose gear/prayers",true);automatic.setToolTipText("Enabled by default: selected-NPC runs scan Orion's local NPC stats and choose the lowest-defence attack style plus the highest-threat protection prayer. The Nieve task loop always scans automatically.");
  JPanel settings=new JPanel(new GridLayout(7,2,8,7));settings.add(new JLabel("Mob profile"));settings.add(mode);settings.add(new JLabel("Number to kill"));settings.add(amount);settings.add(new JLabel("Camp HP (0 = off)"));settings.add(hp);settings.add(new JLabel("Camp prayer points (0 = off)"));settings.add(points);settings.add(new JLabel("Automatic combat profile"));settings.add(automatic);settings.add(new JLabel("Offensive prayer (manual)"));settings.add(offensive);settings.add(new JLabel("Defensive prayer (manual)"));settings.add(defensive);
  JTextArea superiorNames=new JTextArea(fighter.superiorNamesText(),3,36);superiorNames.setLineWrap(true);superiorNames.setWrapStyleWord(true);JScrollPane superiorScroll=new JScrollPane(superiorNames);superiorScroll.setPreferredSize(new Dimension(610,64));superiorScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE,64));
  JPanel top=new JPanel();top.setLayout(new BoxLayout(top,BoxLayout.Y_AXIS));top.add(selected);top.add(Box.createVerticalStrut(12));top.add(settings);top.add(Box.createVerticalStrut(8));top.add(new JLabel("Superior NPC names (one per line, or comma-separated)"));top.add(superiorScroll);top.add(Box.createVerticalStrut(10));top.add(progress);top.add(new JLabel("Nieve loop always scans local NPC stats for offensive gear/style and defensive prayer."));top.add(new JLabel("Listed superior NPCs are killed after the current target, without consuming task progress."));top.add(new JLabel("Tormented demons requires verified Orion mechanics before use."));for(Component part:top.getComponents())if(part instanceof JComponent){((JComponent)part).setAlignmentX(Component.LEFT_ALIGNMENT);if(part instanceof JLabel)part.setMaximumSize(new Dimension(Integer.MAX_VALUE,part.getPreferredSize().height));}root.add(top,BorderLayout.NORTH);
  JPanel actions=new JPanel(new GridLayout(3,2,8,8));JButton pick=new JButton("Select NPC in game"),last=new JButton("Use last killed"),start=new JButton("Start selected NPC"),loop=new JButton("Start Nieve task loop"),stop=new JButton("Stop / F9"),saveSuperiors=new JButton("Save superior list");for(JButton b:new JButton[]{pick,last,start,loop,stop,saveSuperiors})actions.add(b);root.add(actions,BorderLayout.CENTER);root.add(new JScrollPane(status),BorderLayout.SOUTH);setContentPane(root);setSize(680,740);setMinimumSize(new Dimension(680,740));setLocationByPlatform(true);
  pick.addActionListener(e->runtime.thread.invoke(fighter::pick));last.addActionListener(e->runtime.thread.invoke(()->{try{fighter.lastKilled();}catch(RuntimeException error){fighter.status=error.getMessage();}}));
  start.addActionListener(e->{try{amount.commitEdit();hp.commitEdit();points.commitEdit();}catch(java.text.ParseException error){status.setText("Enter whole numbers within the allowed ranges.");return;}int killGoal=(Integer)amount.getValue(),hpTarget=(Integer)hp.getValue(),prayerTarget=(Integer)points.getValue();boolean auto=automatic.isSelected();String superiorText=superiorNames.getText();SlayerController.MobMode profile=SlayerController.MobMode.values()[mode.getSelectedIndex()];net.runelite.api.Prayer attack=prayer(offensive),protection=prayer(defensive);runtime.thread.invoke(()->{try{fighter.updateSuperiorNames(superiorText);fighter.automaticProfile=auto;fighter.offensivePrayer=attack;fighter.defensivePrayer=protection;fighter.mobMode=profile;fighter.survival.hp=hpTarget;fighter.survival.prayer=prayerTarget;fighter.start(killGoal);SwingUtilities.invokeLater(()->focusGame(runtime));}catch(RuntimeException error){fighter.status=error.getMessage();}});});
  loop.addActionListener(e->{try{hp.commitEdit();points.commitEdit();}catch(java.text.ParseException error){status.setText("Enter whole numbers within the allowed ranges.");return;}int hpTarget=(Integer)hp.getValue(),prayerTarget=(Integer)points.getValue();boolean auto=automatic.isSelected();String superiorText=superiorNames.getText();net.runelite.api.Prayer attack=prayer(offensive),protection=prayer(defensive);runtime.thread.invoke(()->{try{fighter.updateSuperiorNames(superiorText);fighter.automaticProfile=auto;fighter.offensivePrayer=attack;fighter.defensivePrayer=protection;fighter.survival.hp=hpTarget;fighter.survival.prayer=prayerTarget;fighter.startTaskLoop();SwingUtilities.invokeLater(()->focusGame(runtime));}catch(RuntimeException error){fighter.status=error.getMessage();}});});
  saveSuperiors.addActionListener(e->{String superiorText=superiorNames.getText();runtime.thread.invoke(()->fighter.updateSuperiorNames(superiorText));});
  stop.addActionListener(e->runtime.thread.invoke(()->runtime.stop("Slayer Stop")));
  timer=new Timer(150,e->{selected.setText("Selected: "+fighter.selected);progress.setText(fighter.progress()+" | Name privacy: "+runtime.privacy.status);status.setText(fighter.status);boolean editing=!fighter.running();for(JComponent control:new JComponent[]{mode,amount,hp,points,automatic,start,loop,superiorNames,saveSuperiors})control.setEnabled(editing);offensive.setEnabled(editing&&!automatic.isSelected());defensive.setEnabled(editing&&!automatic.isSelected());});timer.start();
  addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){runtime.thread.invoke(()->runtime.stop("Slayer window closed"));dispose();}});
 }
 private static JComboBox<String> choices(String... values){return new JComboBox<>(values);}
 private static net.runelite.api.Prayer prayer(JComboBox<String> choice){String name=(String)choice.getSelectedItem();return "None".equals(name)?null:net.runelite.api.Prayer.valueOf(name.toUpperCase(java.util.Locale.ROOT).replace(' ','_'));}
 private static void select(JComboBox<String> choice,net.runelite.api.Prayer prayer){if(prayer!=null)for(int i=0;i<choice.getItemCount();i++)if(choice.getItemAt(i).replace(' ','_').equalsIgnoreCase(prayer.name()))choice.setSelectedIndex(i);}
 private static void focusGame(CombatRuntime runtime){java.awt.Canvas canvas=runtime.client.getCanvas();if(canvas==null)return;Window game=SwingUtilities.getWindowAncestor(canvas);if(game!=null){game.toFront();game.requestFocus();}canvas.requestFocusInWindow();}
 @Override public void dispose(){timer.stop();super.dispose();}
}
